document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll(".tab-btn"),t=document.querySelectorAll(".tab-panel");e.forEach(c=>{c.addEventListener("click",()=>{e.forEach(e=>e.classList.remove("active")),t.forEach(e=>e.classList.remove("active")),c.classList.add("active"),document.getElementById(`tab-${c.dataset.tab}`)?.classList.add("active")})});const c=document.querySelector(".wishlist-btn");c&&c.addEventListener("click",()=>{c.classList.toggle("active");const e=c.querySelector("i");e.classList.toggle("fa-regular"),e.classList.toggle("fa-solid")});const a=document.getElementById("toggleReviewForm"),s=document.getElementById("addReviewForm");a&&s&&a.addEventListener("click",()=>{s.hidden=!s.hidden})});